{
  "hypothesis": "Short-term reversal after abnormally high-volume days in small-cap stocks",
  "factors": [
    {
      "name": "Volatility Gap",
      "expression": "RANK(TS_QUANTILE($volume, 20, 0.9) - TS_QUANTILE($volume, 20, 0.1))",
      "explanation": "Measures the spread between top and bottom volume quantiles over 20 days, ranking stocks based on extreme volume dispersion"
    },
    {
      "name": "Volume Residual",
      "expression": "REGRESI($volume, SEQUENCE(20), 20) - $volume",
      "explanation": "Captures volume deviations from a time trend, highlighting abnormal volume patterns that may signal impending reversals"
    },
    {
      "name": "Momentum Shift",
      "expression": "TS_PCTCHANGE(TS_MEAN($return, 5), 1) * TS_ZSCORE($volume, 10)",
      "explanation": "Weights recent return momentum by volume volatility, emphasizing stocks with divergent price and volume dynamics"
    },
    {
      "name": "Volume Asymmetry",
      "expression": "TS_ARGMAX($volume, 10) - TS_ARGMIN($volume, 10)",
      "explanation": "Identifies stocks where extreme volume occurs at different times within a 10-day window, capturing asymmetric liquidity shifts"
    },
    {
      "name": "Volume Dispersion",
      "expression": "TS_MAD($volume, 20) / TS_STD($volume, 20)",
      "explanation": "Normalizes volume variability relative to its standard deviation, highlighting stocks with unusually volatile trading activity"
    },
    {
      "name": "Volume Lagged Impact",
      "expression": "DELAY(TS_ZSCORE($volume, 10), 1) * TS_PCTCHANGE($return, 1)",
      "explanation": "Combines lagged volume normalization with recent return changes, capturing delayed market reactions to volume spikes"
    }
  ]
}

