{
  "hypothesis": "Low-volatility stocks exhibit mean-reversion during regime transitions, as measured by the gap between high and low returns in a rolling window.",
  "factors": [
    {
      "name": "vol_gap_zscore",
      "expression": "RANK(ZSCORE(TS_QUANTILE($return, 20, 0.9) - TS_QUANTILE($return, 20, 0.1), 20))",
      "explanation": "Computes the gap between upper and lower quantiles of returns in a 20-day window, z-scores it, and ranks to capture mean-reversion in low-volatility stocks."
    },
    {
      "name": "vol_skew_resid",
      "expression": "RANK(SKEW(REGRESI($return, $volume, 30), 30))",
      "explanation": "Uses regression residuals of returns on volume to isolate price movements, then applies skewness to detect asymmetry in low-volatility regimes."
    },
    {
      "name": "vol_mad_diff",
      "expression": "RANK((TS_MAD($return, 60) - TS_MAD($return, 10)) / TS_MAD($return, 60))",
      "explanation": "Measures dispersion change between short and long windows, normalizes by long-term volatility, and ranks to highlight regime shifts."
    },
    {
      "name": "vol_bb_dist",
      "expression": "RANK((BB_UPPER($return, 20, 2) - BB_LOWER($return, 20, 2)) / (BB_UPPER($return, 20, 2) + BB_LOWER($return, 20, 2)))",
      "explanation": "Calculates the normalized Bollinger Band width for low-volatility stocks, ranks it to capture regime transitions via volatility expansion."
    },
    {
      "name": "vol_quantile_diff",
      "expression": "RANK(TS_QUANTILE($return, 60, 0.8) - TS_QUANTILE($return, 60, 0.2))",
      "explanation": "Captures the spread between high and low quantiles in a 60-day window to identify mean-reversion opportunities in low-volatility regimes."
    },
    {
      "name": "vol_decay_diff",
      "expression": "RANK(DECAYLINEAR(TS_PCTCHANGE($return, 10), 20) - DECAYLINEAR(TS_PCTCHANGE($return, 30), 20))",
      "explanation": "Compares decayed percentage changes over different timeframes to detect structural shifts in low-volatility return patterns."
    }
  ]
}
